INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "王延羲", "aliases": ["王曦"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国宗室，王继鹏的叔父，曾任左仆射、同平章事。939年被政变军队拥立，自称威武节度使、闽国王，更名王曦，改元永隆。生卒年暂未核实。", "biography": null, "status": "draft", "id": "e706d6ae-56f4-5e44-9d24-f3060ae87cbb"}, {"name": "王亚澄", "aliases": ["王亞澄"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽王王延羲的儿子。941年四月被任命为同平章事，主管六军诸卫。生卒年未载。", "biography": null, "status": "draft", "id": "bdfe7b21-c8f9-5a2a-8792-e061e8da5652"}, {"name": "王延喜", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽王王延羲的弟弟，汀州刺史。941年四月王延羲怀疑他与王延政串通，派许仁钦率兵将他拘捕带回。串通是王延羲的怀疑，原文没有确认。生卒年未载。", "biography": null, "status": "draft", "id": "a3856e32-2a9d-5720-ac05-bb42733a3fbe"}, {"name": "王延政", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：王延政，都教练使、赴建州抚慰者。", "biography": null, "status": "draft", "id": "83601670-f3dc-5559-b599-e39bda91eb6c"}, {"name": "许仁钦", "aliases": ["許仁欽"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国将军。941年四月奉王延羲之命，率三千兵前往汀州，拘捕王延喜并带回。生卒年未载。", "biography": null, "status": "draft", "id": "ef9f512b-169f-5a8b-aa2f-3ddd1abd2583"}, {"name": "李昪", "aliases": ["徐知诰", "知诰"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷260乾宁二年条所见人物：李昪。", "biography": null, "status": "draft", "id": "5a8b1ad8-1e2e-5318-ae39-1ab3a3e244f9"}, {"name": "陈觉", "aliases": ["陳覺"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：陈觉，海陵人、参与谈议者。", "biography": null, "status": "draft", "id": "8f8c34eb-c238-596f-a688-8b8332b405a1"}, {"name": "常梦锡", "aliases": ["常夢錫"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐官员，万年人。941年四月与陈觉一起被李昪任命为宣徽副使。生卒年未据本段确定。", "biography": null, "status": "draft", "id": "9eaabd48-0b3a-5cc3-a5ec-f9107c987328"}, {"name": "李德珫", "aliases": ["李德充"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋建雄节度使。940年三月调任北都留守。《旧五代史》同次从晋州到北京的调任写作李德充，按任职与行动对应识别为同一人，保留原文字形说明。生卒年未载。", "biography": null, "status": "draft", "id": "0263c149-1d66-5360-8ad2-9b565aa3d34e"}, {"name": "白承福", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "吐谷浑酋长。941年四月辛巳，北京留守李德珫派牙校带领白承福入朝。原文没有说明他是否就是此前归附后晋的某支未具名部众首领。生卒年未据本段确定。", "biography": null, "status": "draft", "id": "404c2172-d65b-534b-aed5-a6e9f5850b6a"}, {"name": "欧阳遇", "aliases": ["歐陽遇"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐通事舍人。941年四月受李昪派遣，向后晋请求借道通往契丹，石敬瑭拒绝请求。生卒年未载。", "biography": null, "status": "draft", "id": "4154d4de-8429-57e1-a2d3-d5c5cb9d435b"}, {"name": "石敬瑭", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：石敬瑭。", "biography": null, "status": "draft", "id": "bf42d98c-7477-5be1-a767-867fe26cf617"}, {"name": "刘岩", "aliases": ["刘龑", "劉巖", "劉龑", "劉岩", "刘巖"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷267开平四年条所见人物：刘岩。", "biography": null, "status": "draft", "id": "3b676280-64ca-5ba9-b78d-c6c5f257a018"}, {"name": "安从进", "aliases": ["安從進"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：安从进，受询的侍卫都指挥使。", "biography": null, "status": "draft", "id": "3b1f48e5-6ce0-58cd-add7-1bdf9f0d4812"}, {"name": "孟昶", "aliases": ["孟仁赞", "孟仁贊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275天成二年条所见人物：孟昶，孟子、被迎者。", "biography": null, "status": "draft", "id": "666201f7-9186-590e-8d5b-2a4a605dba69"}, {"name": "高从诲", "aliases": ["高從誨"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷273同光三年条所见人物：高从诲。", "biography": null, "status": "draft", "id": "361de308-8df0-56e4-ac98-81f6b9297e26"}, {"name": "王保义", "aliases": ["王保義"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "荆南行军司马。941年安从进筹划反叛后晋、向荆南求援，王保义劝高从诲向朝廷详报情况，并请求派兵协助朝廷讨伐，高从诲听从。新五代史还记他曾是高季兴的宾客，具体起年未载。生卒年未载。", "biography": null, "status": "draft", "id": "6d4b0146-5477-5b75-90ef-b4ebf3099645"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "王延羲任儿子王亚澄为同平章事，并主管六军诸卫", "start_year": 941, "end_year": 941, "time_original": "941年四月条下，具体日期未载", "dynasty": "五代十国", "description": "王延羲任儿子王亚澄为同平章事，并主管六军诸卫。", "phases": [], "location_name": "闽国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "098c136e-c542-586e-8c94-2f738cb94d89"}, {"title": "王延羲怀疑王延喜与王延政串通", "start_year": 941, "end_year": 941, "time_original": "941年四月条下，具体日期未载", "dynasty": "五代十国", "description": "王延羲怀疑王延喜与王延政串通。", "phases": [], "location_name": "闽国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "bc0e95ca-5f18-5b87-841b-c147572593bd"}, {"title": "许仁钦率三千兵赴汀州，拘捕王延喜并带回", "start_year": 941, "end_year": 941, "time_original": "941年四月条下，具体日期未载", "dynasty": "五代十国", "description": "许仁钦率三千兵赴汀州，拘捕王延喜并带回。", "phases": [], "location_name": "汀州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "0cc42932-edb8-5e88-807c-45be58deda3e"}, {"title": "李昪任陈觉、常梦锡为宣徽副使", "start_year": 941, "end_year": 941, "time_original": "941年四月条下，具体日期未载", "dynasty": "五代十国", "description": "李昪任陈觉、常梦锡为宣徽副使。", "phases": [], "location_name": "南唐", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "f4c15ddb-457c-5be2-b25a-56ac785f2d1c"}, {"title": "李德珫派牙校带领吐谷浑酋长白承福入朝", "start_year": 941, "end_year": 941, "time_original": "941年四月辛巳", "dynasty": "五